/* eslint-disable jsx-a11y/anchor-is-valid */
/* eslint-disable no-lone-blocks */
import React, { Component } from 'react';
import {Table, Card,Tabs} from 'antd'; 
import { withRouter } from 'react-router-dom';
import {getTransactions} from '../../services/Api'
const { TabPane } = Tabs;
function callback(key) {
	console.log(key);
  }
class Transactions extends Component {	
	constructor(props){
		super(props)
	this.state = {transactions:[]};

	this.viewCoin = ()=> {
		props.history.push("/viewcoins");
	  };

    // this.getCryptoData = async ()=> {

	//  let data = await CryptoCoinsOnDashboard();
	// 	  this.setState({
	// 		cryptodata:data
	// 	  });


	//  };

	this.otherpage=(text)=>{

		 this.props.history.push({
			pathname: '/viewcoin',
			coin: text,
		  });
	 };
	}   

	async componentDidMount(){		   
        trackPromise(
          this.getTransactions().then(result=>{
          console.log("hii data hapa", result)

           this.setState({ 
            transactions:result,
           })
      }	
      )
      )

    }

    async getTransactions(){
       const Transaction= await getTransactions();
        // console.log(Orders);
       return Transaction;
    }


	render() {  
		const total = this.state.transactions.length;
	const columns = [
		{
			title: 'Date',
			dataIndex: 'createdAt',
			key: 'createdAt',
			render: text => <img style={{height:30,width:30}} alt="" src={text}></img>,

		  },
		{
			title: 'Customer Name',
			dataIndex: 'name',
			key: 'name',

			render: (text) => (
				<span>
				<a style={{color:'green'}} onClick={()=>this.otherpage(text)}> {text}</a>

				</span>
			),
            },
            {
                title: 'Customer Contact',
                dataIndex: 'phone',
                key: 'phone',

                render: (text) => (
                    <span>
                    <a style={{color:'green'}} onClick={()=>this.otherpage(text)}> {text}</a>

                    </span>
                ),
                },
			{
			title: ' Price Paid',
			dataIndex: 'pricepaid',
			key: 'lastprice',
			render: text => <a style={{color:'#555555'}}>{text}</a>,
            },
            {
            title: ' Transaction Type',
            dataIndex: 'pricepaid',
            key: 'lastprice',
            render: text => <a style={{color:'#555555'}}>{text}</a>,
            },
			{
			title: 'Vendor Name',
			dataIndex: 'vendorname',
			key: 'vendorname',
			render:text => <a style={{color:'#555555'}}>{text}</a>,      

			},
			{
				title: 'Product',
				dataIndex:'product',
				key: 'product',
				render: text =><a style={{color:'#555555'}}>{text}</a> 	
			},
			{
			title: 'Quantity of Product',
			dataIndex:'productquantity',
			key: 'productquantity',
			render: text =><a style={{color:'#555555'}}>{text}</a> 	
		},			  
		];
		return (
	<div>

                <Card title="All Transactions "  bodyStyle={{padding:0}} loading={false}>
					<div className="table-responsive">
					<Table columns={columns} dataSource={this.state.transactions} limit={10}  scroll={{ x: 1200 }}  onPress={()=>this.viewCoin()} pagination={{size:'small', total:total, showTotal:total => `Total ${total} Coins`}}  />
					</div>
				</Card>


	</div>
		);
	}
}
export default withRouter(Transactions);
